import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class Main {
    record Parsed(String level, String service, String message) {}
    static Parsed parse(String line) {
        String[] fields = line.split("\\|", 3);
        if (fields.length != 3 || fields[0].isBlank() || fields[1].isBlank()) throw new IllegalArgumentException("bad log line");
        return new Parsed(fields[0], fields[1], fields[2]);
    }
    public static void main(String[] args) {
        List<String> lines = List.of("ERROR|billing|timeout", "INFO|auth|started", "ERROR|auth|denied", "ERROR|billing|retry");
        List<Parsed> parsed = lines.stream().map(Main::parse).toList();
        Map<String, Long> counts = parsed.stream().filter(row -> row.level().equals("ERROR"))
                .collect(Collectors.groupingBy(Parsed::service, TreeMap::new, Collectors.counting()));
        if (!counts.equals(Map.of("auth", 1L, "billing", 2L))) throw new AssertionError(counts);
        try { parse("ERROR|missing-message"); throw new AssertionError("malformed accepted"); }
        catch (IllegalArgumentException expected) { System.out.println("Malformed log line rejected."); }
        System.out.println("Error counts: " + counts);
        System.out.println("Log parsing assertions passed.");
    }
}"}

{"path": "code/S18/JH-S18-009/Main.java", "executed": true, "java": "Temurin 21.0.12.1", "output": "Bounded executor rejected overflow and completed accepted tasks.", "source": "import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class Main {
    public static void main(String[] args) throws InterruptedException {
        CountDownLatch release = new CountDownLatch(1), completed = new CountDownLatch(2);
        ThreadPoolExecutor pool = new ThreadPoolExecutor(1, 1, 0, TimeUnit.MILLISECONDS,
                new ArrayBlockingQueue<>(1), new ThreadPoolExecutor.AbortPolicy());
        pool.execute(() -> { try { release.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } finally { completed.countDown(); } });
        pool.execute(completed::countDown);
        boolean rejected = false;
        try { pool.execute(() -> {}); } catch (java.util.concurrent.RejectedExecutionException expected) { rejected = true; }
        if (!rejected) throw new AssertionError("queue should reject overflow");
        release.countDown(); pool.shutdown();
        if (!pool.awaitTermination(2, TimeUnit.SECONDS) || completed.getCount() != 0) throw new AssertionError("tasks incomplete");
        System.out.println("Bounded executor rejected overflow and completed accepted tasks.");
    }
}"}

{"path": "code/S18/JH-S18-010/Main.java", "executed": true, "java": "Temurin 21.0.12.1", "output": "Negative transfer rejected.
Opposite-direction transfers finished; total cents: 2000", "source": "import java.util.concurrent.CountDownLatch;

public class Main {
    static final class Account {
        final int id; int cents;
        Account(int id, int cents) { this.id = id; this.cents = cents; }
    }
    static void transfer(Account from, Account to, int cents) {
        if (cents < 0) throw new IllegalArgumentException("negative transfer");
        Account first = from.id < to.id ? from : to, second = from.id < to.id ? to : from;
        synchronized (first) { synchronized (second) {
            if (from.cents < cents) throw new IllegalStateException("insufficient funds");
            from.cents -= cents; to.cents += cents;
        }}
    }
    public static void main(String[] args) throws InterruptedException {
        Account a = new Account(1, 1_000), b = new Account(2, 1_000);
        CountDownLatch start = new CountDownLatch(1);
        Thread left = new Thread(() -> { try { start.await(); for (int i=0;i<500;i++) transfer(a,b,1); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } });
        Thread right = new Thread(() -> { try { start.await(); for (int i=0;i<500;i++) transfer(b,a,1); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } });
        left.start(); right.start(); start.countDown(); left.join(2_000); right.join(2_000);
        if (left.isAlive() || right.isAlive()) throw new AssertionError("lock-order deadlock");
        if (a.cents + b.cents != 2_000) throw new AssertionError("money lost");
        try { transfer(a,b,-1); throw new AssertionError("negative accepted"); }
        catch (IllegalArgumentException expected) { System.out.println("Negative transfer rejected."); }
        System.out.println("Opposite-direction transfers finished; total cents: " + (a.cents + b.cents));
    }
}"}

{"path": "code/S18/JH-S18-011/Main.java", "executed": true, "java": "Temurin 21.0.12.1", "output": "Closed lease rejected; resource returned once.", "source": "import java.util.concurrent.ArrayBlockingQueue;

public class Main {
    static final class Pool {
        private final ArrayBlockingQueue<String> available;
        Pool(String... resources) { available = new ArrayBlockingQueue<>(resources.length); for (String r : resources) available.add(r); }
        Lease acquire() { String resource = available.poll(); return resource == null ? null : new Lease(resource); }
        final class Lease implements AutoCloseable {
            private String resource;
            Lease(String resource) { this.resource = resource; }
            String value() { if (resource == null) throw new IllegalStateException("lease closed"); return resource; }
            public void close() { if (resource != null) { String returned = resource; resource = null; if (!available.offer(returned)) throw new IllegalStateException("double return"); } }
        }
    }
    public static void main(String[] args) {
        Pool pool = new Pool("connection-1"); Pool.Lease lease = pool.acquire();
        if (!"connection-1".equals(lease.value()) || pool.acquire() != null) throw new AssertionError("exhaustion");
        lease.close(); lease.close();
        Pool.Lease reused = pool.acquire();
        if (!"connection-1".equals(reused.value())) throw new AssertionError("reuse");
        reused.close();
        try { reused.value(); throw new AssertionError("closed lease usable"); }
        catch (IllegalStateException expected) { System.out.println("Closed lease rejected; resource returned once."); }
    }
}"}

