{"path": "code/S18/JH-S18-030/Main.java", "executed": true, "java": "Temurin 21.0.12.1", "output": "Listener failure isolated; active listeners: 2", "source": "import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

public class Main {
    static final class Dispatcher<T> {
        private final CopyOnWriteArrayList<Consumer<T>> listeners=new CopyOnWriteArrayList<>();
        void add(Consumer<T> listener){listeners.add(listener);}void remove(Consumer<T> listener){listeners.remove(listener);}
        int publish(T event){int failures=0;for(Consumer<T> listener:listeners)try{listener.accept(event);}catch(RuntimeException failure){failures++;}return failures;}
        int size(){return listeners.size();}
    }
    public static void main(String[] args){Dispatcher<String> bus=new Dispatcher<>();StringBuilder seen=new StringBuilder();Consumer<String> later=seen::append;
        bus.add(event->{seen.append("first-");bus.remove(later);});bus.add(event->{throw new IllegalStateException("subscriber failure");});bus.add(later);
        if(bus.publish("event")!=1||!seen.toString().equals("first-event")||bus.size()!=2)throw new AssertionError(seen);
        if(bus.publish("next")!=1||!seen.toString().equals("first-eventfirst-"))throw new AssertionError("snapshot semantics");
        System.out.println("Listener failure isolated; active listeners: "+bus.size());}
}"}

{"path": "code/S18/JH-S18-031/Main.java", "executed": true, "java": "Temurin 21.0.12.1", "output": "Invalid retry bound rejected.
Dead-lettered after bounded attempts: [Job[id=event-a, attempts=3]]", "source": "import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.function.Predicate;

public class Main {
    record Job(String id,int attempts) {}
    static final class Worker {
        private final int maxAttempts;private final Queue<Job> ready=new ArrayDeque<>(),dead=new ArrayDeque<>();
        Worker(int maxAttempts){if(maxAttempts<1)throw new IllegalArgumentException();this.maxAttempts=maxAttempts;}
        void submit(String id){ready.add(new Job(id,0));}
        void drain(Predicate<Job> succeeds){while(!ready.isEmpty()){Job job=ready.remove();if(succeeds.test(job))continue;Job failed=new Job(job.id(),job.attempts()+1);if(failed.attempts()<maxAttempts)ready.add(failed);else dead.add(failed);}}
        List<Job> deadLetters(){return List.copyOf(dead);}
    }
    public static void main(String[] args){Worker worker=new Worker(3);worker.submit("event-a");worker.submit("event-b");worker.drain(job->job.id().equals("event-b"));
        if(!worker.deadLetters().equals(List.of(new Job("event-a",3))))throw new AssertionError(worker.deadLetters());
        try{new Worker(0);throw new AssertionError("zero retries");}catch(IllegalArgumentException expected){System.out.println("Invalid retry bound rejected.");}
        System.out.println("Dead-lettered after bounded attempts: "+worker.deadLetters());}
}"}

{"path": "code/S18/JH-S18-032/Main.java", "executed": true, "java": "Temurin 21.0.12.1", "output": "Stable merged feed: [a, b, d, e]", "source": "import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

public class Main {
    record Log(long time,int source,int offset,String message) {}
    static List<Log> merge(List<List<Log>> feeds){PriorityQueue<Log> heap=new PriorityQueue<>(Comparator.comparingLong(Log::time).thenComparingInt(Log::source));
        int[] positions=new int[feeds.size()];for(int i=0;i<feeds.size();i++){if(!feeds.get(i).isEmpty())heap.add(feeds.get(i).get(0));}
        List<Log> result=new ArrayList<>();while(!heap.isEmpty()){Log next=heap.remove();result.add(next);int p=++positions[next.source()];if(p<feeds.get(next.source()).size())heap.add(feeds.get(next.source()).get(p));}return List.copyOf(result);}
    public static void main(String[] args){List<Log> merged=merge(List.of(List.of(new Log(1,0,0,"a"),new Log(4,0,1,"d")),List.of(new Log(2,1,0,"b"),new Log(4,1,1,"e"))));
        if(!merged.stream().map(Log::message).toList().equals(List.of("a","b","d","e")))throw new AssertionError(merged);
        if(!merge(List.of(List.of())).isEmpty())throw new AssertionError("empty feeds");
        System.out.println("Stable merged feed: "+merged.stream().map(Log::message).toList());}
}"}

