[] -> []", "source": "import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.List;

public class Main {
    static List<Integer> removeAdjacentDuplicates(int[] values) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int value : values) {
            if (!stack.isEmpty() && stack.peek() == value) stack.pop();
            else stack.push(value);
        }
        List<Integer> result = new ArrayList<>(stack);
        Collections.reverse(result);
        return result;
    }

    public static void main(String[] args) {
        int[][] inputs = {{1, 2, 2, 3, 3, 1}, {1, 2, 5, 4, 2, 3}, {1, 1, 1}, {}};
        for (int[] input : inputs) {
            System.out.println(Arrays.toString(input) + " -> " + removeAdjacentDuplicates(input));
        }
    }
}
"}

{"path": "code/S18/JH-S18-045/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "DFS (mutates a copy): 3
BFS (visited array):  3
input grid left untouched: true", "source": "import java.util.ArrayDeque;
import java.util.Queue;

public class Main {
    static int countDfs(char[][] original) {
        char[][] grid = copy(original);
        int count = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '1') {
                    count++;
                    sink(grid, r, c);
                }
            }
        }
        return count;
    }

    private static void sink(char[][] g, int r, int c) {
        if (r < 0 || c < 0 || r >= g.length || c >= g[0].length || g[r][c] != '1') return;
        g[r][c] = '0';
        sink(g, r + 1, c);
        sink(g, r - 1, c);
        sink(g, r, c + 1);
        sink(g, r, c - 1);
    }

    static int countBfs(char[][] grid) {
        int rows = grid.length, cols = grid[0].length, count = 0;
        boolean[][] seen = new boolean[rows][cols];
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '1' || seen[r][c]) continue;
                count++;
                Queue<int[]> queue = new ArrayDeque<>();
                queue.add(new int[]{r, c});
                seen[r][c] = true;
                while (!queue.isEmpty()) {
                    int[] cur = queue.poll();
                    for (int[] d : dirs) {
                        int nr = cur[0] + d[0], nc = cur[1] + d[1];
                        if (nr >= 0 && nc >= 0 && nr < rows && nc < cols && grid[nr][nc] == '1' && !seen[nr][nc]) {
                            seen[nr][nc] = true;
                            queue.add(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
        return count;
    }

    private static char[][] copy(char[][] g) {
        char[][] c = new char[g.length][];
        for (int i = 0; i < g.length; i++) c[i] = g[i].clone();
        return c;
    }

    public static void main(String[] args) {
        char[][] grid = {
                "11000".toCharArray(),
                "11000".toCharArray(),
                "00100".toCharArray(),
                "00011".toCharArray()};
        System.out.println("DFS (mutates a copy): " + countDfs(grid));
        System.out.println("BFS (visited array):  " + countBfs(grid));
        System.out.println("input grid left untouched: " + (grid[0][0] == '1'));
    }
}
"}

