{"path": "code/S18/JH-S18-047/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "sorted-string key: [[eat, tea, ate], [tan, nat], [bat]]
letter-count key:  [[eat, tea, ate], [tan, nat], [bat]]", "source": "import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {
    static List<List<String>> bySortedKey(String[] words) {
        Map<String, List<String>> groups = new LinkedHashMap<>();
        for (String w : words) {
            char[] chars = w.toCharArray();
            Arrays.sort(chars);
            groups.computeIfAbsent(new String(chars), k -> new ArrayList<>()).add(w);
        }
        return new ArrayList<>(groups.values());
    }

    static List<List<String>> byCountKey(String[] words) {
        Map<String, List<String>> groups = new LinkedHashMap<>();
        for (String w : words) {
            int[] counts = new int[26];
            for (char ch : w.toCharArray()) counts[ch - 'a']++;
            StringBuilder key = new StringBuilder();
            for (int c : counts) key.append('#').append(c);
            groups.computeIfAbsent(key.toString(), k -> new ArrayList<>()).add(w);
        }
        return new ArrayList<>(groups.values());
    }

    public static void main(String[] args) {
        String[] words = {"eat", "tea", "tan", "ate", "nat", "bat"};
        System.out.println("sorted-string key: " + bySortedKey(words));
        System.out.println("letter-count key:  " + byCountKey(words));
    }
}
"}

{"path": "code/S18/JH-S18-048/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "[3, 5, 1, 9, 2, 8] min=1 max=9 pairwise comparisons=7 naive=10
[7, 2, 9, 4, 6, 1, 5] min=1 max=9 pairwise comparisons=9 naive=12", "source": "import java.util.Arrays;

public class Main {
    static int comparisons;

    static boolean less(int a, int b) {
        comparisons++;
        return a < b;
    }

    static int[] minMax(int[] a) {
        int n = a.length, min, max, i;
        if (n % 2 == 0) {
            if (less(a[0], a[1])) { min = a[0]; max = a[1]; } else { min = a[1]; max = a[0]; }
            i = 2;
        } else {
            min = max = a[0];
            i = 1;
        }
        while (i < n - 1) {
            int lo, hi;
            if (less(a[i], a[i + 1])) { lo = a[i]; hi = a[i + 1]; } else { lo = a[i + 1]; hi = a[i]; }
            if (less(lo, min)) min = lo;
            if (less(max, hi)) max = hi;
            i += 2;
        }
        return new int[]{min, max};
    }

    public static void main(String[] args) {
        int[][] inputs = {{3, 5, 1, 9, 2, 8}, {7, 2, 9, 4, 6, 1, 5}};
        for (int[] input : inputs) {
            comparisons = 0;
            int[] result = minMax(input);
            int n = input.length;
            System.out.println(Arrays.toString(input) + " min=" + result[0] + " max=" + result[1]
                    + " pairwise comparisons=" + comparisons + " naive=" + 2 * (n - 1));
        }
    }
}
"}

