[0,3,7,2,5,8,4,6,0,1] -> 9
[] -> 0", "source": "import java.util.HashSet;
import java.util.Set;

public class Main {
    static int longestConsecutive(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int n : nums) set.add(n);
        int best = 0;
        for (int n : set) {
            if (set.contains(n - 1)) continue;
            int current = n, length = 1;
            while (set.contains(current + 1)) {
                current++;
                length++;
            }
            best = Math.max(best, length);
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println("[100,4,200,1,3,2] -> " + longestConsecutive(new int[]{100, 4, 200, 1, 3, 2}));
        System.out.println("[0,3,7,2,5,8,4,6,0,1] -> " + longestConsecutive(new int[]{0, 3, 7, 2, 5, 8, 4, 6, 0, 1}));
        System.out.println("[] -> " + longestConsecutive(new int[]{}));
    }
}
"}

{"path": "code/S18/JH-S18-050/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "fixed window, max sum of size 3 in [5,3,1,4,7,9]: 20
dynamic window, longest unique substring 'abcabcbb': 3
dynamic window, longest unique substring 'pwwkew': 3
dynamic window, shortest subarray with sum >= 7 in [2,3,1,2,4,3]: 2", "source": "import java.util.HashMap;
import java.util.Map;

public class Main {
    static int maxSumOfSizeK(int[] a, int k) {
        int sum = 0;
        for (int i = 0; i < k; i++) sum += a[i];
        int best = sum;
        for (int i = k; i < a.length; i++) {
            sum += a[i] - a[i - k];
            best = Math.max(best, sum);
        }
        return best;
    }

    static int longestWithoutRepeat(String s) {
        Map<Character, Integer> last = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (last.containsKey(c)) left = Math.max(left, last.get(c) + 1);
            last.put(c, right);
            best = Math.max(best, right - left + 1);
        }
        return best;
    }

    static int shortestSubarrayAtLeast(int[] a, int target) {
        int left = 0, sum = 0, best = Integer.MAX_VALUE;
        for (int right = 0; right < a.length; right++) {
            sum += a[right];
            while (sum >= target) {
                best = Math.min(best, right - left + 1);
                sum -= a[left++];
            }
        }
        return best == Integer.MAX_VALUE ? 0 : best;
    }

    public static void main(String[] args) {
        System.out.println("fixed window, max sum of size 3 in [5,3,1,4,7,9]: " + maxSumOfSizeK(new int[]{5, 3, 1, 4, 7, 9}, 3));
        System.out.println("dynamic window, longest unique substring 'abcabcbb': " + longestWithoutRepeat("abcabcbb"));
        System.out.println("dynamic window, longest unique substring 'pwwkew': " + longestWithoutRepeat("pwwkew"));
        System.out.println("dynamic window, shortest subarray with sum >= 7 in [2,3,1,2,4,3]: "
                + shortestSubarrayAtLeast(new int[]{2, 3, 1, 2, 4, 3}, 7));
    }
}
"}

{"path": "code/S18/JH-S18-051/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "any subset sums to 9: true
any subset sums to 30: false
all subsets that sum to 9: [[3, 4, 2], [4, 5]]
two-sum indices in [2,7,11,15] for 9: [0, 1]", "source": "import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Main {
    static boolean subsetSumExists(int[] a, int target) {
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;
        for (int num : a) {
            for (int t = target; t >= num; t--) dp[t] |= dp[t - num];
        }
        return dp[target];
    }

    static void allSubsets(int[] a, int index, int remaining, List<Integer> current, List<List<Integer>> out) {
        if (remaining == 0) {
            out.add(new ArrayList<>(current));
            return;
        }
        if (index == a.length || remaining < 0) return;
        current.add(a[index]);
        allSubsets(a, index + 1, remaining - a[index], current, out);
        current.remove(current.size() - 1);
        allSubsets(a, index + 1, remaining, current, out);
    }

    static int[] twoSum(int[] a, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < a.length; i++) {
            Integer j = seen.get(target - a[i]);
            if (j != null) return new int[]{j, i};
            seen.put(a[i], i);
        }
        return new int[0];
    }

    public static void main(String[] args) {
        int[] a = {3, 34, 4, 12, 5, 2};
        System.out.println("any subset sums to 9: " + subsetSumExists(a, 9));
        System.out.println("any subset sums to 30: " + subsetSumExists(a, 30));
        List<List<Integer>> subsets = new ArrayList<>();
        allSubsets(a, 0, 9, new ArrayList<>(), subsets);
        System.out.println("all subsets that sum to 9: " + subsets);
        System.out.println("two-sum indices in [2,7,11,15] for 9: " + Arrays.toString(twoSum(new int[]{2, 7, 11, 15}, 9)));
    }
}
"}

{"path": "code/S18/JH-S18-052/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "abc by swapping (6): [abc, acb, bac, bca, cba, cab]
aab unique (3): [aab, aba, baa]", "source": "import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    static void permuteBySwap(char[] c, int left, List<String> out) {
        if (left == c.length - 1) {
            out.add(new String(c));
            return;
        }
        for (int i = left; i < c.length; i++) {
            swap(c, left, i);
            permuteBySwap(c, left + 1, out);
            swap(c, left, i);
        }
    }

    static void permuteUnique(char[] sorted, boolean[] used, StringBuilder cur, List<String> out) {
        if (cur.length() == sorted.length) {
            out.add(cur.toString());
            return;
        }
        for (int i = 0; i < sorted.length; i++) {
            if (used[i]) continue;
            if (i > 0 && sorted[i] == sorted[i - 1] && !used[i - 1]) continue;
            used[i] = true;
            cur.append(sorted[i]);
            permuteUnique(sorted, used, cur, out);
            cur.deleteCharAt(cur.length() - 1);
            used[i] = false;
        }
    }

    private static void swap(char[] c, int i, int j) {
        char t = c[i];
        c[i] = c[j];
        c[j] = t;
    }

    public static void main(String[] args) {
        List<String> swapped = new ArrayList<>();
        permuteBySwap("abc".toCharArray(), 0, swapped);
        System.out.println("abc by swapping (" + swapped.size() + "): " + swapped);

        char[] aab = "aab".toCharArray();
        Arrays.sort(aab);
        List<String> unique = new ArrayList<>();
        permuteUnique(aab, new boolean[aab.length], new StringBuilder(), unique);
        System.out.println("aab unique (" + unique.size() + "): " + unique);
    }
}
"}

{"path": "code/S18/JH-S18-053/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "36 -> [1, 2, 3, 4, 6, 9, 12, 18, 36] | same result: true | loop iterations 36 vs 6
28 -> [1, 2, 4, 7, 14, 28] | same result: true | loop iterations 28 vs 5
97 -> [1, 97] | same result: true | loop iterations 97 vs 9", "source": "import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Main {
    static int iterations;

    static List<Integer> bruteForce(int n) {
        List<Integer> result = new ArrayList<>();
        iterations = 0;
        for (int i = 1; i <= n; i++) {
            iterations++;
            if (n % i == 0) result.add(i);
        }
        return result;
    }

    static List<Integer> viaSquareRoot(int n) {
        List<Integer> small = new ArrayList<>(), large = new ArrayList<>();
        iterations = 0;
        for (int i = 1; (long) i * i <= n; i++) {
            iterations++;
            if (n % i == 0) {
                small.add(i);
                if (i != n / i) large.add(n / i);
            }
        }
        Collections.reverse(large);
        small.addAll(large);
        return small;
    }

    public static void main(String[] args) {
        for (int n : new int[]{36, 28, 97}) {
            List<Integer> slow = bruteForce(n);
            int slowIterations = iterations;
            List<Integer> fast = viaSquareRoot(n);
            System.out.println(n + " -> " + fast + " | same result: " + slow.equals(fast)
                    + " | loop iterations " + slowIterations + " vs " + iterations);
        }
    }
}
"}

{"path": "code/S18/JH-S18-054/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "501224 smallest (zeros allowed): 012245
501224 smallest (no leading zero): 102245
501224 largest: 542210
234 smallest: 234", "source": "public class Main {
    static String smallest(String digits) {
        int[] count = counts(digits);
        StringBuilder sb = new StringBuilder();
        for (int d = 0; d <= 9; d++) sb.append(String.valueOf((char) ('0' + d)).repeat(count[d]));
        return sb.toString();
    }

    static String smallestNoLeadingZero(String digits) {
        int[] count = counts(digits);
        int first = -1;
        for (int d = 1; d <= 9; d++) {
            if (count[d] > 0) { first = d; break; }
        }
        if (first == -1) return "0";
        count[first]--;
        StringBuilder sb = new StringBuilder().append((char) ('0' + first));
        for (int d = 0; d <= 9; d++) sb.append(String.valueOf((char) ('0' + d)).repeat(count[d]));
        return sb.toString();
    }

    static String largest(String digits) {
        int[] count = counts(digits);
        StringBuilder sb = new StringBuilder();
        for (int d = 9; d >= 0; d--) sb.append(String.valueOf((char) ('0' + d)).repeat(count[d]));
        return sb.toString();
    }

    private static int[] counts(String digits) {
        int[] count = new int[10];
        for (char c : digits.toCharArray()) count[c - '0']++;
        return count;
    }

    public static void main(String[] args) {
        System.out.println("501224 smallest (zeros allowed): " + smallest("501224"));
        System.out.println("501224 smallest (no leading zero): " + smallestNoLeadingZero("501224"));
        System.out.println("501224 largest: " + largest("501224"));
        System.out.println("234 smallest: " + smallest("234"));
    }
}
"}

{"path": "code/S18/JH-S18-055/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "sea, eat -> 231
delete, leet -> 403
abc, abc -> 0", "source": "public class Main {
    static int minimumDeleteSum(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        int[][] dp = new int[m + 1][n + 1];
        for (int i = 1; i <= m; i++) dp[i][0] = dp[i - 1][0] + s1.charAt(i - 1);
        for (int j = 1; j <= n; j++) dp[0][j] = dp[0][j - 1] + s2.charAt(j - 1);
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (s1.charAt(i - 1) == s2.charAt(j - 1)) dp[i][j] = dp[i - 1][j - 1];
                else dp[i][j] = Math.min(dp[i - 1][j] + s1.charAt(i - 1), dp[i][j - 1] + s2.charAt(j - 1));
            }
        }
        return dp[m][n];
    }

    public static void main(String[] args) {
        System.out.println("sea, eat -> " + minimumDeleteSum("sea", "eat"));
        System.out.println("delete, leet -> " + minimumDeleteSum("delete", "leet"));
        System.out.println("abc, abc -> " + minimumDeleteSum("abc", "abc"));
    }
}
"}

{"path": "code/S18/JH-S18-056/Main.java", "executed": true, "java": "OpenJDK 21.0.10 (Ubuntu build)", "output": "headcount by department id: {1=3, 2=2, 3=1}
largest department: Engineering with designations [Developer, Tester]", "source": "import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class Main {
    record Employee(int empId, int deptId, String designation) {}
    record Department(int deptId, String departmentName) {}

    public static void main(String[] args) {
        List<Department> departments = List.of(
                new Department(1, "Engineering"), new Department(2, "HR"), new Department(3, "Finance"));
        List<Employee> employees = List.of(
                new Employee(101, 1, "Developer"), new Employee(102, 1, "Developer"), new Employee(103, 1, "Tester"),
                new Employee(104, 2, "Recruiter"), new Employee(105, 2, "Manager"),
                new Employee(106, 3, "Analyst"));

        Map<Integer, Long> countByDept = employees.stream()
                .collect(Collectors.groupingBy(Employee::deptId, TreeMap::new, Collectors.counting()));
        System.out.println("headcount by department id: " + countByDept);

        int topDeptId = countByDept.entrySet().stream()
                .max(Map.Entry.<Integer, Long>comparingByValue().thenComparing(Map.Entry.<Integer, Long>comparingByKey().reversed()))
                .map(Map.Entry::getKey)
                .orElseThrow();

        String name = departments.stream().filter(d -> d.deptId() == topDeptId)
                .map(Department::departmentName).findFirst().orElse("UNKNOWN");
        List<String> designations = employees.stream().filter(e -> e.deptId() == topDeptId)
                .map(Employee::designation).distinct().toList();
        System.out.println("largest department: " + name + " with designations " + designations);
    }
}
"}
